-- Profiles (ADR 0068). Generated by drizzle-kit, then edited by hand where it can't know the data:
-- every account gets its own profile, sharing the account's id and named as the account is, and
-- the watch state, playback picks and Home already recorded move to it (the owner's answer 15 in
-- phase-5-real-use.md). The three watch tables and home_layouts are rebuilt for their new keys:
-- nothing references them, so their DROP TABLE cascades nowhere, and the migrator's transaction
-- keeps foreign keys on, where `PRAGMA foreign_keys` is a no-op (sqlite.org/pragma.html#pragma_foreign_keys).
CREATE TABLE `profiles` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`name` text NOT NULL,
	`tone` text NOT NULL,
	`pin_hash` text,
	`main` integer DEFAULT false NOT NULL,
	`pin_failures` integer DEFAULT 0 NOT NULL,
	`pin_rest_until` integer,
	`created_at` integer NOT NULL,
	`updated_at` integer NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
--> statement-breakpoint
CREATE INDEX `profiles_user` ON `profiles` (`user_id`,`created_at`);--> statement-breakpoint
INSERT INTO `profiles` (`id`, `user_id`, `name`, `tone`, `pin_hash`, `main`, `pin_failures`, `pin_rest_until`, `created_at`, `updated_at`)
SELECT `id`, `id`, `display_name`, 'accent', NULL, 1, 0, NULL, `created_at`, `created_at` FROM `users`
WHERE NOT EXISTS (SELECT 1 FROM `profiles` p WHERE p.`id` = `users`.`id`);--> statement-breakpoint
PRAGMA foreign_keys=OFF;--> statement-breakpoint
